    Assert.assertEquals(-1, comp.compare(Intervals.of("2011-04-01/2011-04-03"), Intervals.of("2011-04-01/2011-04-04")));
    Interval[] intervals = new Interval[] { Intervals.of("2011-04-01T18/2011-04-02T13"), Intervals.of("2011-04-01/2011-04-03"), Intervals.of("2011-04-01/2011-04-04"), Intervals.of("2011-04-02/2011-04-04"), Intervals.of("2011-04-01/2011-04-02"), Intervals.of("2011-04-02/2011-04-03"), Intervals.of("2011-04-02/2011-04-03T06") };
