@Test
public void testClosingOfSequenceSequence() throws Exception {
    final int[] closedCount = { 0 };
    final Sequence<Integer> seq = Sequences.concat(new BaseSequence<>(new BaseSequence.IteratorMaker<Sequence<Integer>, Iterator<Sequence<Integer>>>() {

        @Override
        public Iterator<Sequence<Integer>> make() {
            return Arrays.asList(Sequences.simple(Arrays.asList(1, 2, 3, 4)), Sequences.simple(Arrays.asList(5, 6, 7, 8))).iterator();
        }

        @Override
        public void cleanup(Iterator<Sequence<Integer>> iterFromMake) {
            ++closedCount[0];
        }
    }));
    Assert.assertEquals(9, seq.accumulate(1, new Accumulator<Integer, Integer>() {

        @Override
        public Integer accumulate(Integer accumulated, Integer in) {
            Assert.assertEquals(accumulated, in);
            return accumulated + 1;
        }
    }).intValue());
    Assert.assertEquals(1, closedCount[0]);
    final Yielder<Integer> yielder = seq.toYielder(1, new YieldingAccumulator<Integer, Integer>() {

        @Override
        public Integer accumulate(Integer accumulated, Integer in) {
            Assert.assertEquals(accumulated, in);
            return accumulated + 1;
        }
    });
    Assert.assertEquals(9, yielder.get().intValue());
    Assert.assertEquals(1, closedCount[0]);
    yielder.close();
    Assert.assertEquals(2, closedCount[0]);
}

