@Test
public void buildingSketchesAtIngestionTime() throws Exception {
    Sequence<Row> seq = helper.createIndexAndRunQueryOnSegment(new File(this.getClass().getClassLoader().getResource("doubles_build_data.tsv").getFile()), String.join("\n", "{", "  \"type\": \"string\",", "  \"parseSpec\": {", "    \"format\": \"tsv\",", "    \"timestampSpec\": {\"column\": \"timestamp\", \"format\": \"yyyyMMddHH\"},", "    \"dimensionsSpec\": {", "      \"dimensions\": [\"product\"],", "      \"dimensionExclusions\": [ \"sequenceNumber\"],", "      \"spatialDimensions\": []", "    },", "    \"columns\": [\"timestamp\", \"sequenceNumber\", \"product\", \"value\"]", "  }", "}"), "[{\"type\": \"momentSketch\", \"name\": \"sketch\", \"fieldName\": \"value\", \"k\": 10, \"compress\": true}]", 0, // minTimestamp
    Granularities.NONE, 10, // maxRowCount
    String.join("\n", "{", "  \"queryType\": \"groupBy\",", "  \"dataSource\": \"test_datasource\",", "  \"granularity\": \"ALL\",", "  \"dimensions\": [],", "  \"aggregations\": [", "    {\"type\": \"momentSketchMerge\", \"name\": \"sketch\", \"fieldName\": \"sketch\", \"k\": 10, \"compress\": true}", "  ],", "  \"postAggregations\": [", "    {\"type\": \"momentSketchSolveQuantiles\", \"name\": \"quantiles\", \"fractions\": [0, 0.5, 1], \"field\": {\"type\": \"fieldAccess\", \"fieldName\": \"sketch\"}},", "    {\"type\": \"momentSketchMin\", \"name\": \"min\", \"field\": {\"type\": \"fieldAccess\", \"fieldName\": \"sketch\"}},", "    {\"type\": \"momentSketchMax\", \"name\": \"max\", \"field\": {\"type\": \"fieldAccess\", \"fieldName\": \"sketch\"}}", "  ],", "  \"intervals\": [\"2016-01-01T00:00:00.000Z/2016-01-31T00:00:00.000Z\"]", "}"));
    List<Row> results = seq.toList();
    assertEquals(1, results.size());
    Row row = results.get(0);
    double[] quantilesArray = (double[]) row.getRaw("quantiles");
    assertEquals(0, quantilesArray[0], 0.05);
    assertEquals(.5, quantilesArray[1], 0.05);
    assertEquals(1.0, quantilesArray[2], 0.05);
    Double minValue = (Double) row.getRaw("min");
    assertEquals(0.0011, minValue, 0.0001);
    Double maxValue = (Double) row.getRaw("max");
    assertEquals(0.9969, maxValue, 0.0001);
    MomentSketchWrapper sketchObject = (MomentSketchWrapper) row.getRaw("sketch");
    assertEquals(400.0, sketchObject.getPowerSums()[0], 1e-10);
}

