@Test
public void testPauseWithSubsequentGetOffsets() throws Exception {
    Capture<Request> captured = Capture.newInstance();
    Capture<Request> captured2 = Capture.newInstance();
    Capture<Request> captured3 = Capture.newInstance();
    // one time in IndexTaskClient.submitRequest() and another in KafkaIndexTaskClient.pause()
    expect(responseHolder.getStatus()).andReturn(HttpResponseStatus.ACCEPTED).times(2).andReturn(HttpResponseStatus.OK).anyTimes();
    expect(responseHolder.getContent()).andReturn("\"PAUSED\"").times(2).andReturn("{\"0\":1, \"1\":10}").anyTimes();
    expect(httpClient.go(EasyMock.capture(captured), EasyMock.anyObject(FullResponseHandler.class), EasyMock.eq(TEST_HTTP_TIMEOUT))).andReturn(Futures.immediateFuture(responseHolder));
    expect(httpClient.go(EasyMock.capture(captured2), EasyMock.anyObject(FullResponseHandler.class), EasyMock.eq(TEST_HTTP_TIMEOUT))).andReturn(Futures.immediateFuture(responseHolder));
    expect(httpClient.go(EasyMock.capture(captured3), EasyMock.anyObject(FullResponseHandler.class), EasyMock.eq(TEST_HTTP_TIMEOUT))).andReturn(Futures.immediateFuture(responseHolder));
    replayAll();
    Map<Integer, Long> results = client.pause(TEST_ID);
    verifyAll();
    Request request = captured.getValue();
    Assert.assertEquals(HttpMethod.POST, request.getMethod());
    Assert.assertEquals(new URL("http://test-host:1234/druid/worker/v1/chat/test-id/pause"), request.getUrl());
    Assert.assertTrue(request.getHeaders().get("X-Druid-Task-Id").contains("test-id"));
    request = captured2.getValue();
    Assert.assertEquals(HttpMethod.GET, request.getMethod());
    Assert.assertEquals(new URL("http://test-host:1234/druid/worker/v1/chat/test-id/status"), request.getUrl());
    request = captured3.getValue();
