@Test(timeout = 120_000L)
public void testIncrementalHandOff() throws Exception {
    final String baseSequenceName = "sequence0";
    // as soon as any segment has more than one record, incremental publishing should happen
    maxRowsPerSegment = 2;
    maxRecordsPerPoll = 1;
    recordSupplier.assign(anyObject());
    expectLastCall().anyTimes();
    expect(recordSupplier.getEarliestSequenceNumber(anyObject())).andReturn("0").anyTimes();
    recordSupplier.seek(anyObject(), anyString());
    expectLastCall().anyTimes();
    expect(recordSupplier.poll(anyLong())).andReturn(records.subList(0, 5)).once().andReturn(records.subList(4, records.size())).once();
    recordSupplier.close();
    expectLastCall().once();
    replayAll();
    final SeekableStreamStartSequenceNumbers<String, String> startPartitions = new SeekableStreamStartSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "0", shardId0, "0"), ImmutableSet.of());
    final SeekableStreamEndSequenceNumbers<String, String> checkpoint1 = new SeekableStreamEndSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "4", shardId0, "0"));
    final SeekableStreamEndSequenceNumbers<String, String> endPartitions = new SeekableStreamEndSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "9", shardId0, "1"));
    final KinesisIndexTask task = createTask(null, new KinesisIndexTaskIOConfig(0, baseSequenceName, startPartitions, endPartitions, true, null, null, "awsEndpoint", null, null, null, null, false));
    final ListenableFuture<TaskStatus> future = runTask(task);
    while (task.getRunner().getStatus() != SeekableStreamIndexTaskRunner.Status.PAUSED) {
        Thread.sleep(10);
    }
    final Map<String, String> currentOffsets = ImmutableMap.copyOf(task.getRunner().getCurrentOffsets());
    Assert.assertEquals(checkpoint1.getPartitionSequenceNumberMap(), currentOffsets);
    task.getRunner().setEndOffsets(currentOffsets, false);
    Assert.assertEquals(TaskState.SUCCESS, future.get().getStatusCode());
    verifyAll();
    Assert.assertEquals(1, checkpointRequestsHash.size());
    Assert.assertTrue(checkpointRequestsHash.contains(Objects.hash(DATA_SCHEMA.getDataSource(), 0, new KinesisDataSourceMetadata(startPartitions), new KinesisDataSourceMetadata(new SeekableStreamEndSequenceNumbers<>(stream, currentOffsets)))));
    // Check metrics
    Assert.assertEquals(8, task.getRunner().getRowIngestionMeters().getProcessed());
    Assert.assertEquals(4, task.getRunner().getRowIngestionMeters().getUnparseable());
    Assert.assertEquals(0, task.getRunner().getRowIngestionMeters().getThrownAway());
    // Check published metadata
    SegmentDescriptor desc1 = sd(task, "2008/P1D", 0);
    SegmentDescriptor desc2 = sd(task, "2009/P1D", 0);
    SegmentDescriptor desc3 = sd(task, "2010/P1D", 0);
    SegmentDescriptor desc4 = sd(task, "2011/P1D", 0);
    SegmentDescriptor desc5 = sd(task, "2011/P1D", 1);
    SegmentDescriptor desc6 = sd(task, "2012/P1D", 0);
    SegmentDescriptor desc7 = sd(task, "2013/P1D", 0);
    Assert.assertEquals(ImmutableSet.of(desc1, desc2, desc3, desc4, desc5, desc6, desc7), publishedDescriptors());
    Assert.assertEquals(new KinesisDataSourceMetadata(new SeekableStreamEndSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "9", shardId0, "1"))), metadataStorageCoordinator.getDataSourceMetadata(DATA_SCHEMA.getDataSource()));
    // Check segments in deep storage
    Assert.assertEquals(ImmutableList.of("a"), readSegmentColumn("dim1", desc1));
    Assert.assertEquals(ImmutableList.of("b"), readSegmentColumn("dim1", desc2));
    Assert.assertEquals(ImmutableList.of("c"), readSegmentColumn("dim1", desc3));
    Assert.assertTrue((ImmutableList.of("d", "e").equals(readSegmentColumn("dim1", desc4)) && ImmutableList.of("h").equals(readSegmentColumn("dim1", desc5))) || (ImmutableList.of("d", "h").equals(readSegmentColumn("dim1", desc4)) && ImmutableList.of("e").equals(readSegmentColumn("dim1", desc5))));
    Assert.assertEquals(ImmutableList.of("g"), readSegmentColumn("dim1", desc6));
    Assert.assertEquals(ImmutableList.of("f"), readSegmentColumn("dim1", desc7));
}

