    // Insert data
    final SeekableStreamStartSequenceNumbers<String, String> startPartitions = new SeekableStreamStartSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "0"), ImmutableSet.of());
    // Checkpointing will happen at either checkpoint1 or checkpoint2 depending on ordering
    // of events fetched across two partitions from Kafka
    final SeekableStreamEndSequenceNumbers<String, String> checkpoint1 = new SeekableStreamEndSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "2"));
    final SeekableStreamEndSequenceNumbers<String, String> checkpoint2 = new SeekableStreamEndSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "9"));
    final SeekableStreamEndSequenceNumbers<String, String> endPartitions = new SeekableStreamEndSequenceNumbers<>(stream, ImmutableMap.of(shardId1, "10"));
    final KinesisIndexTask task = createTask(null, new KinesisIndexTaskIOConfig(0, baseSequenceName, startPartitions, endPartitions, true, null, null, "awsEndpoint", null, null, null, null, false));
    final ListenableFuture<TaskStatus> future = runTask(task);
    while (task.getRunner().getStatus() != Status.PAUSED) {
        Thread.sleep(10);
    }
    final Map<String, String> currentOffsets = ImmutableMap.copyOf(task.getRunner().getCurrentOffsets());
    Assert.assertEquals(checkpoint1.getPartitionSequenceNumberMap(), currentOffsets);
    task.getRunner().setEndOffsets(currentOffsets, false);
    while (task.getRunner().getStatus() != Status.PAUSED) {
        Thread.sleep(10);
    }
    final Map<String, String> nextOffsets = ImmutableMap.copyOf(task.getRunner().getCurrentOffsets());
    Assert.assertEquals(checkpoint2.getPartitionSequenceNumberMap(), nextOffsets);
    task.getRunner().setEndOffsets(nextOffsets, false);
    Assert.assertEquals(TaskState.SUCCESS, future.get().getStatusCode());
    verifyAll();
    Assert.assertEquals(2, checkpointRequestsHash.size());
    Assert.assertTrue(checkpointRequestsHash.contains(Objects.hash(DATA_SCHEMA.getDataSource(), 0, new KinesisDataSourceMetadata(startPartitions), new KinesisDataSourceMetadata(new SeekableStreamEndSequenceNumbers<>(stream, currentOffsets)))));
    Assert.assertTrue(checkpointRequestsHash.contains(Objects.hash(DATA_SCHEMA.getDataSource(), 0, new KinesisDataSourceMetadata(new SeekableStreamStartSequenceNumbers<>(stream, currentOffsets, currentOffsets.keySet())), new KinesisDataSourceMetadata(new SeekableStreamEndSequenceNumbers<>(stream, nextOffsets)))));
    // Check metrics
    Assert.assertEquals(6, task.getRunner().getRowIngestionMeters().getProcessed());
    Assert.assertEquals(4, task.getRunner().getRowIngestionMeters().getUnparseable());
    Assert.assertEquals(0, task.getRunner().getRowIngestionMeters().getThrownAway());
    // Check published metadata
    SegmentDescriptor desc1 = sd(task, "2008/P1D", 0);
    SegmentDescriptor desc2 = sd(task, "2009/P1D", 0);
    SegmentDescriptor desc3 = sd(task, "2010/P1D", 0);
    SegmentDescriptor desc4 = sd(task, "2011/P1D", 0);
    SegmentDescriptor desc5 = sd(task, "2049/P1D", 0);
