    verifyAll();
    EasyMock.reset(taskRunner, taskClient, taskQueue);
    EasyMock.expect(taskRunner.getRunningTasks()).andReturn(workItems).anyTimes();
    EasyMock.expect(taskClient.pauseAsync("id2")).andReturn(Futures.immediateFuture((Map<String, String>) ImmutableMap.of(shardId1, "12", shardId0, "1")));
    EasyMock.expect(taskClient.setEndOffsetsAsync("id2", ImmutableMap.of(shardId1, "12", shardId0, "1"), true)).andReturn(Futures.immediateFuture(true));
    taskQueue.shutdown("id3", "Killing task for graceful shutdown");
    expectLastCall().times(1);
    taskQueue.shutdown("id3", "Killing task [%s] which hasn't been assigned to a worker", "id3");
    expectLastCall().times(1);
    EasyMock.replay(taskRunner, taskClient, taskQueue);
    supervisor.gracefulShutdownInternal();
    verifyAll();
}

