@Test
public void testIsTaskCurrent() {
    DateTime minMessageTime = DateTimes.nowUtc();
    DateTime maxMessageTime = DateTimes.nowUtc().plus(10000);
    KinesisSupervisor supervisor = getSupervisor(1, 1, true, "PT1H", new Period("P1D"), new Period("P1D"), false, 42, 42, dataSchema, tuningConfig);
    supervisor.addTaskGroupToActivelyReadingTaskGroup(42, ImmutableMap.of(shardId1, "3"), Optional.of(minMessageTime), Optional.of(maxMessageTime), ImmutableSet.of("id1", "id2", "id3", "id4"), ImmutableSet.of());
    DataSchema modifiedDataSchema = getDataSchema("some other datasource");
    KinesisSupervisorTuningConfig modifiedTuningConfig = new KinesisSupervisorTuningConfig(1000, null, 50000, null, new Period("P1Y"), new File("/test"), null, null, true, false, null, null, null, null, numThreads, TEST_CHAT_THREADS, TEST_CHAT_RETRIES, TEST_HTTP_TIMEOUT, TEST_SHUTDOWN_TIMEOUT, null, null, null, 5000, null, null, null, null, // This property is different from tuningConfig
    42, null);
    KinesisIndexTask taskFromStorage = createKinesisIndexTask("id1", 0, new SeekableStreamStartSequenceNumbers<>("stream", ImmutableMap.of(shardId1, "3"), ImmutableSet.of()), new SeekableStreamEndSequenceNumbers<>("stream", ImmutableMap.of(shardId1, KinesisSequenceNumber.NO_END_SEQUENCE_NUMBER)), minMessageTime, maxMessageTime, dataSchema);
    KinesisIndexTask taskFromStorageMismatchedDataSchema = createKinesisIndexTask("id2", 0, new SeekableStreamStartSequenceNumbers<>("stream", ImmutableMap.of(shardId1, "3"), ImmutableSet.of()), new SeekableStreamEndSequenceNumbers<>("stream", ImmutableMap.of(shardId1, KinesisSequenceNumber.NO_END_SEQUENCE_NUMBER)), minMessageTime, maxMessageTime, modifiedDataSchema);
    KinesisIndexTask taskFromStorageMismatchedTuningConfig = createKinesisIndexTask("id3", 0, new SeekableStreamStartSequenceNumbers<>("stream", ImmutableMap.of(shardId1, "3"), ImmutableSet.of()), new SeekableStreamEndSequenceNumbers<>("stream", ImmutableMap.of(shardId1, KinesisSequenceNumber.NO_END_SEQUENCE_NUMBER)), minMessageTime, maxMessageTime, dataSchema, modifiedTuningConfig);
    KinesisIndexTask taskFromStorageMismatchedPartitionsWithTaskGroup = createKinesisIndexTask("id4", 0, new SeekableStreamStartSequenceNumbers<>("stream", ImmutableMap.of(shardId1, // this is the mismatch
    "4"), ImmutableSet.of()), new SeekableStreamEndSequenceNumbers<>("stream", ImmutableMap.of(shardId1, KinesisSequenceNumber.NO_END_SEQUENCE_NUMBER)), minMessageTime, maxMessageTime, dataSchema);
    EasyMock.expect(taskStorage.getTask("id1")).andReturn(Optional.of(taskFromStorage)).once();
    EasyMock.expect(taskStorage.getTask("id2")).andReturn(Optional.of(taskFromStorageMismatchedDataSchema)).once();
    EasyMock.expect(taskStorage.getTask("id3")).andReturn(Optional.of(taskFromStorageMismatchedTuningConfig)).once();
    EasyMock.expect(taskStorage.getTask("id4")).andReturn(Optional.of(taskFromStorageMismatchedPartitionsWithTaskGroup)).once();
    replayAll();
    Assert.assertTrue(supervisor.isTaskCurrent(42, "id1"));
    Assert.assertFalse(supervisor.isTaskCurrent(42, "id2"));
    Assert.assertFalse(supervisor.isTaskCurrent(42, "id3"));
    Assert.assertFalse(supervisor.isTaskCurrent(42, "id4"));
    verifyAll();
}

