    }
    // Revoke some locks
    for (int i = 0; i < 4; i++) {
        final Task task = NoopTask.create(100);
        highPriorityTasks.add(task);
        taskStorage.insert(task, TaskStatus.running(task.getId()));
        lockbox.add(task);
