        Assert.assertFalse(taskStorage.getLocks(highPriorityTasks.get(i).getId()).stream().allMatch(TaskLock::isRevoked));
    }
    for (int i = 4; i < 8; i++) {
        Assert.assertFalse(taskStorage.getLocks(lowPriorityTasks.get(i).getId()).stream().allMatch(TaskLock::isRevoked));
    }
    for (int i = 0; i < 4; i++) {
        lockbox.unlock(lowPriorityTasks.get(i), Intervals.of(StringUtils.format("2017-01-0%d/2017-01-0%d", (i + 1), (i + 2))));
        lockbox.unlock(highPriorityTasks.get(i), Intervals.of(StringUtils.format("2017-01-0%d/2017-01-0%d", (i + 1), (i + 2))));
    }
    for (int i = 4; i < 8; i++) {
        lockbox.unlock(lowPriorityTasks.get(i), Intervals.of(StringUtils.format("2017-01-0%d/2017-01-0%d", (i + 1), (i + 2))));
