    Assert.assertTrue(lockbox.tryLock(TaskLockType.EXCLUSIVE, lowPriorityTask, Intervals.of("2018-12-16T09:00:00/2018-12-16T10:00:00")).isOk());
    Assert.assertTrue(lockbox.tryLock(TaskLockType.EXCLUSIVE, highPriorityTask, Intervals.of("2018-12-16T09:00:00/2018-12-16T09:30:00")).isOk());
    final TaskLockPosse highLockPosse = lockbox.getOnlyTaskLockPosseContainingInterval(highPriorityTask, Intervals.of("2018-12-16T09:00:00/2018-12-16T09:30:00"));
    Assert.assertTrue(highLockPosse.containsTask(highPriorityTask));
    Assert.assertFalse(highLockPosse.getTaskLock().isRevoked());
    final TaskLockPosse lowLockPosse = lockbox.getOnlyTaskLockPosseContainingInterval(lowPriorityTask, Intervals.of("2018-12-16T09:00:00/2018-12-16T10:00:00"));
    Assert.assertTrue(lowLockPosse.containsTask(lowPriorityTask));
    Assert.assertTrue(lowLockPosse.getTaskLock().isRevoked());
}

