@Test
public void testUnionQuery() throws IOException {
    final int numTasks = 3;
    final Closer closer = Closer.create();
    for (int i = 0; i < numTasks; i++) {
        closer.register(unloader(fullDatasourceName + i));
    }
    try {
        // Load 4 datasources with same dimensions
        String task = setShutOffTime(getResourceAsString(UNION_TASK_RESOURCE), DateTimes.utc(System.currentTimeMillis() + TimeUnit.MINUTES.toMillis(3)));
        List<String> taskIDs = new ArrayList<>();
        for (int i = 0; i < numTasks; i++) {
            taskIDs.add(indexer.submitTask(withServiceName(withDataSource(task, fullDatasourceName + i), EVENT_RECEIVER_SERVICE_PREFIX + i)));
        }
        for (int i = 0; i < numTasks; i++) {
            postEvents(i);
        }
        // wait until all events are ingested
        RetryUtil.retryUntil(() -> {
            for (int i = 0; i < numTasks; i++) {
                final int countRows = queryHelper.countRows(fullDatasourceName + i, "2013-08-31/2013-09-01");
                if (countRows < 5) {
                    LOG.warn("%d events have been ingested to %s so far", countRows, fullDatasourceName + i);
                    return false;
                }
            }
            return true;
        }, true, 1000, 100, "Waiting all events are ingested");
        // should hit the queries on realtime task
        LOG.info("Running Union Queries..");
        String queryResponseTemplate;
        try {
            InputStream is = AbstractITBatchIndexTest.class.getResourceAsStream(UNION_QUERIES_RESOURCE);
            queryResponseTemplate = IOUtils.toString(is, "UTF-8");
        } catch (IOException e) {
            throw new ISE(e, "could not read query file: %s", UNION_QUERIES_RESOURCE);
        }
        queryResponseTemplate = StringUtils.replace(queryResponseTemplate, "%%DATASOURCE%%", fullDatasourceName);
        this.queryHelper.testQueriesFromString(queryResponseTemplate, 2);
        // wait for the task to complete
        for (int i = 0; i < numTasks; i++) {
            indexer.waitUntilTaskCompletes(taskIDs.get(i));
        }
        // task should complete only after the segments are loaded by historical node
        for (int i = 0; i < numTasks; i++) {
            final int taskNum = i;
            RetryUtil.retryUntil(new Callable<Boolean>() {

                @Override
                public Boolean call() {
                    return coordinator.areSegmentsLoaded(fullDatasourceName + taskNum);
                }
            }, true, 10000, 10, "Real-time generated segments loaded");
        }
        // run queries on historical nodes
        this.queryHelper.testQueriesFromString(queryResponseTemplate, 2);
    } catch (Throwable e) {
        throw closer.rethrow(e);
    } finally {
        closer.close();
    }
}

