@Test
public void testSystemSchemaAccess() throws Exception {
    HttpClient adminClient = new CredentialedHttpClient(new BasicCredentials("admin", "priest"), httpClient);
    // check that admin access works on all nodes
    checkNodeAccess(adminClient);
    // create a new user+role that can only read 'auth_test'
    List<ResourceAction> readDatasourceOnlyPermissions = Collections.singletonList(new ResourceAction(new Resource("auth_test", ResourceType.DATASOURCE), Action.READ));
    createUserAndRoleWithPermissions(adminClient, "datasourceOnlyUser", "helloworld", "datasourceOnlyRole", readDatasourceOnlyPermissions);
    HttpClient datasourceOnlyUserClient = new CredentialedHttpClient(new BasicCredentials("datasourceOnlyUser", "helloworld"), httpClient);
    // create a new user+role that can only read 'auth_test' + STATE read access
    List<ResourceAction> readDatasourceWithStatePermissions = ImmutableList.of(new ResourceAction(new Resource("auth_test", ResourceType.DATASOURCE), Action.READ), new ResourceAction(new Resource(".*", ResourceType.STATE), Action.READ));
    createUserAndRoleWithPermissions(adminClient, "datasourceWithStateUser", "helloworld", "datasourceWithStateRole", readDatasourceWithStatePermissions);
    HttpClient datasourceWithStateUserClient = new CredentialedHttpClient(new BasicCredentials("datasourceWithStateUser", "helloworld"), httpClient);
    // create a new user+role with only STATE read access
    List<ResourceAction> stateOnlyPermissions = ImmutableList.of(new ResourceAction(new Resource(".*", ResourceType.STATE), Action.READ));
    createUserAndRoleWithPermissions(adminClient, "stateOnlyUser", "helloworld", "stateOnlyRole", stateOnlyPermissions);
    HttpClient stateOnlyUserClient = new CredentialedHttpClient(new BasicCredentials("stateOnlyUser", "helloworld"), httpClient);
    // check that we can access a datasource-permission restricted resource on the broker
    makeRequest(datasourceOnlyUserClient, HttpMethod.GET, config.getBrokerUrl() + "/druid/v2/datasources/auth_test", null);
    // check that we can access a state-permission restricted resource on the broker
    makeRequest(datasourceWithStateUserClient, HttpMethod.GET, config.getBrokerUrl() + "/status", null);
    makeRequest(stateOnlyUserClient, HttpMethod.GET, config.getBrokerUrl() + "/status", null);
    // initial setup is done now, run the system schema response content tests
    final List<Map<String, Object>> adminSegments = jsonMapper.readValue(TestQueryHelper.class.getResourceAsStream(SYSTEM_SCHEMA_SEGMENTS_RESULTS_RESOURCE), SYS_SCHEMA_RESULTS_TYPE_REFERENCE);
    final List<Map<String, Object>> adminServerSegments = jsonMapper.readValue(TestQueryHelper.class.getResourceAsStream(SYSTEM_SCHEMA_SERVER_SEGMENTS_RESULTS_RESOURCE), SYS_SCHEMA_RESULTS_TYPE_REFERENCE);
    final List<Map<String, Object>> adminServers = getServersWithoutCurrentSize(jsonMapper.readValue(TestQueryHelper.class.getResourceAsStream(SYSTEM_SCHEMA_SERVERS_RESULTS_RESOURCE), SYS_SCHEMA_RESULTS_TYPE_REFERENCE));
    final List<Map<String, Object>> adminTasks = jsonMapper.readValue(TestQueryHelper.class.getResourceAsStream(SYSTEM_SCHEMA_TASKS_RESULTS_RESOURCE), SYS_SCHEMA_RESULTS_TYPE_REFERENCE);
    // as admin
    LOG.info("Checking sys.segments query as admin...");
    verifySystemSchemaQuery(adminClient, SYS_SCHEMA_SEGMENTS_QUERY, adminSegments);
    LOG.info("Checking sys.servers query as admin...");
    verifySystemSchemaServerQuery(adminClient, SYS_SCHEMA_SERVERS_QUERY, getServersWithoutCurrentSize(adminServers));
    LOG.info("Checking sys.server_segments query as admin...");
    verifySystemSchemaQuery(adminClient, SYS_SCHEMA_SERVER_SEGMENTS_QUERY, adminServerSegments);
    LOG.info("Checking sys.tasks query as admin...");
    verifySystemSchemaQuery(adminClient, SYS_SCHEMA_TASKS_QUERY, adminTasks);
    // as user that can only read auth_test
    LOG.info("Checking sys.segments query as datasourceOnlyUser...");
    verifySystemSchemaQuery(datasourceOnlyUserClient, SYS_SCHEMA_SEGMENTS_QUERY, adminSegments.stream().filter((segmentEntry) -> {
        return "auth_test".equals(segmentEntry.get("datasource"));
    }).collect(Collectors.toList()));
    LOG.info("Checking sys.servers query as datasourceOnlyUser...");
    verifySystemSchemaQueryFailure(datasourceOnlyUserClient, SYS_SCHEMA_SERVERS_QUERY, HttpResponseStatus.FORBIDDEN, "{\"Access-Check-Result\":\"Insufficient permission to view servers : Allowed:false, Message:\"}");
    LOG.info("Checking sys.server_segments query as datasourceOnlyUser...");
    verifySystemSchemaQueryFailure(datasourceOnlyUserClient, SYS_SCHEMA_SERVER_SEGMENTS_QUERY, HttpResponseStatus.FORBIDDEN, "{\"Access-Check-Result\":\"Insufficient permission to view servers : Allowed:false, Message:\"}");
    LOG.info("Checking sys.tasks query as datasourceOnlyUser...");
    verifySystemSchemaQuery(datasourceOnlyUserClient, SYS_SCHEMA_TASKS_QUERY, adminTasks.stream().filter((taskEntry) -> {
        return "auth_test".equals(taskEntry.get("datasource"));
    }).collect(Collectors.toList()));
    // as user that can read auth_test and STATE
    LOG.info("Checking sys.segments query as datasourceWithStateUser...");
    verifySystemSchemaQuery(datasourceWithStateUserClient, SYS_SCHEMA_SEGMENTS_QUERY, adminSegments.stream().filter((segmentEntry) -> {
        return "auth_test".equals(segmentEntry.get("datasource"));
    }).collect(Collectors.toList()));
    LOG.info("Checking sys.servers query as datasourceWithStateUser...");
    verifySystemSchemaServerQuery(datasourceWithStateUserClient, SYS_SCHEMA_SERVERS_QUERY, adminServers);
    LOG.info("Checking sys.server_segments query as datasourceWithStateUser...");
    verifySystemSchemaQuery(datasourceWithStateUserClient, SYS_SCHEMA_SERVER_SEGMENTS_QUERY, adminServerSegments.stream().filter((serverSegmentEntry) -> {
        return ((String) serverSegmentEntry.get("segment_id")).contains("auth_test");
    }).collect(Collectors.toList()));
    LOG.info("Checking sys.tasks query as datasourceWithStateUser...");
    verifySystemSchemaQuery(datasourceWithStateUserClient, SYS_SCHEMA_TASKS_QUERY, adminTasks.stream().filter((taskEntry) -> {
        return "auth_test".equals(taskEntry.get("datasource"));
    }).collect(Collectors.toList()));
    // as user that can only read STATE
    LOG.info("Checking sys.segments query as stateOnlyUser...");
    verifySystemSchemaQuery(stateOnlyUserClient, SYS_SCHEMA_SEGMENTS_QUERY, Collections.emptyList());
    LOG.info("Checking sys.servers query as stateOnlyUser...");
    verifySystemSchemaServerQuery(stateOnlyUserClient, SYS_SCHEMA_SERVERS_QUERY, adminServers);
    LOG.info("Checking sys.server_segments query as stateOnlyUser...");
    verifySystemSchemaQuery(stateOnlyUserClient, SYS_SCHEMA_SERVER_SEGMENTS_QUERY, Collections.emptyList());
    LOG.info("Checking sys.tasks query as stateOnlyUser...");
    verifySystemSchemaQuery(stateOnlyUserClient, SYS_SCHEMA_TASKS_QUERY, Collections.emptyList());
}

@Test
public void testAuthConfiguration() throws Exception {
    HttpClient adminClient = new CredentialedHttpClient(new BasicCredentials("admin", "priest"), httpClient);
    HttpClient internalSystemClient = new CredentialedHttpClient(new BasicCredentials("druid_system", "warlock"), httpClient);
    HttpClient newUserClient = new CredentialedHttpClient(new BasicCredentials("druid", "helloworld"), httpClient);
    final HttpClient unsecuredClient = httpClient;
    // check that we are allowed to access unsecured path without credentials.
    checkUnsecuredCoordinatorLoadQueuePath(unsecuredClient);
    // check that admin works
    checkNodeAccess(adminClient);
    // check that internal user works
    checkNodeAccess(internalSystemClient);
    // create a new user+role that can read /status
    List<ResourceAction> permissions = Collections.singletonList(new ResourceAction(new Resource(".*", ResourceType.STATE), Action.READ));
    createUserAndRoleWithPermissions(adminClient, "druid", "helloworld", "druidrole", permissions);
    // check that the new user works
    checkNodeAccess(newUserClient);
    // check loadStatus
    checkLoadStatus(adminClient);
    // create 100 users
    for (int i = 0; i < 100; i++) {
        makeRequest(adminClient, HttpMethod.POST, config.getCoordinatorUrl() + "/druid-ext/basic-security/authentication/db/basic/users/druid" + i, null);
        makeRequest(adminClient, HttpMethod.POST, config.getCoordinatorUrl() + "/druid-ext/basic-security/authorization/db/basic/users/druid" + i, null);
        LOG.info("Finished creating user druid" + i);
    }
    // setup the last of 100 users and check that it works
    makeRequest(adminClient, HttpMethod.POST, config.getCoordinatorUrl() + "/druid-ext/basic-security/authentication/db/basic/users/druid99/credentials", jsonMapper.writeValueAsBytes(new BasicAuthenticatorCredentialUpdate("helloworld", 5000)));
    makeRequest(adminClient, HttpMethod.POST, config.getCoordinatorUrl() + "/druid-ext/basic-security/authorization/db/basic/users/druid99/roles/druidrole", null);
    HttpClient newUser99Client = new CredentialedHttpClient(new BasicCredentials("druid99", "helloworld"), httpClient);
    LOG.info("Checking access for user druid99.");
    checkNodeAccess(newUser99Client);
    String brokerUrl = "jdbc:avatica:remote:url=" + config.getBrokerUrl() + DruidAvaticaHandler.AVATICA_PATH;
    String routerUrl = "jdbc:avatica:remote:url=" + config.getRouterUrl() + DruidAvaticaHandler.AVATICA_PATH;
    LOG.info("Checking Avatica query on broker.");
    testAvaticaQuery(brokerUrl);
    LOG.info("Checking Avatica query on router.");
    testAvaticaQuery(routerUrl);
    LOG.info("Testing Avatica query on broker with incorrect credentials.");
    testAvaticaAuthFailure(brokerUrl);
    LOG.info("Testing Avatica query on router with incorrect credentials.");
    testAvaticaAuthFailure(routerUrl);
    LOG.info("Checking OPTIONS requests on services...");
    testOptionsRequests(adminClient);
}

