    0x01, // replaceMissingValueWith
    0x66, // replaceMissingValueWith
    0x6F, // replaceMissingValueWith
    0x6F, // replaceMissingValueWith
    0x62, // replaceMissingValueWith
    0x61, // replaceMissingValueWith
    0x72, // replaceMissingValueWith
