@Test
public void testBuildWithExplicitOrder() {
    DefaultLimitSpec limitSpec = new DefaultLimitSpec(ImmutableList.of(new OrderByColumnSpec("k1", OrderByColumnSpec.Direction.ASCENDING)), 2);
    Function<Sequence<Row>, Sequence<Row>> limitFn = limitSpec.build(ImmutableList.of(new DefaultDimensionSpec("k1", "k1")), ImmutableList.of(new LongSumAggregatorFactory("k2", "k2")), ImmutableList.of(new ConstantPostAggregator("k3", 1L)), Granularities.NONE, false);
    Assert.assertEquals(ImmutableList.of(testRowsList.get(0), testRowsList.get(1)), limitFn.apply(testRowsSequence).toList());
    // if there is an aggregator with same name then that is used to build ordering
    limitFn = limitSpec.build(ImmutableList.of(new DefaultDimensionSpec("k1", "k1")), ImmutableList.of(new LongSumAggregatorFactory("k1", "k1")), ImmutableList.of(new ConstantPostAggregator("k3", 1L)), Granularities.NONE, false);
    Assert.assertEquals(ImmutableList.of(testRowsList.get(2), testRowsList.get(0)), limitFn.apply(testRowsSequence).toList());
    // if there is a post-aggregator with same name then that is used to build ordering
    limitFn = limitSpec.build(ImmutableList.of(new DefaultDimensionSpec("k1", "k1")), ImmutableList.of(new LongSumAggregatorFactory("k2", "k2")), ImmutableList.of(new ArithmeticPostAggregator("k1", "+", ImmutableList.of(new ConstantPostAggregator("x", 1), new ConstantPostAggregator("y", 1)))), Granularities.NONE, false);
    Assert.assertEquals((List) ImmutableList.of(testRowsList.get(2), testRowsList.get(0)), (List) limitFn.apply(testRowsSequence).toList());
    // makes same result
    limitFn = limitSpec.build(ImmutableList.of(new DefaultDimensionSpec("k1", "k1")), ImmutableList.of(new LongSumAggregatorFactory("k2", "k2")), ImmutableList.of(new ExpressionPostAggregator("k1", "1 + 1", null, TestExprMacroTable.INSTANCE)), Granularities.NONE, false);
    Assert.assertEquals((List) ImmutableList.of(testRowsList.get(2), testRowsList.get(0)), (List) limitFn.apply(testRowsSequence).toList());
}

