// Validates that getResultOrdering will work for the broker n-way merge
@Test
public void testMergeSequenceForResults() {
    // Should be able to handle merging s1, s2, s3
    ScanQuery noOrderScan = Druids.newScanQueryBuilder().order(ScanQuery.Order.NONE).resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_LIST).dataSource("some src").intervals(intervalSpec).build();
    // Should only handle s1 and s2
    ScanQuery descendingOrderScan = Druids.newScanQueryBuilder().order(ScanQuery.Order.DESCENDING).resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_LIST).dataSource("some src").intervals(intervalSpec).build();
    // Should only handle s1 and s2
    ScanQuery ascendingOrderScan = Druids.newScanQueryBuilder().order(ScanQuery.Order.ASCENDING).resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_LIST).dataSource("some src").intervals(intervalSpec).build();
    // No Order
    Sequence<ScanResultValue> noOrderSeq = Sequences.simple(ImmutableList.of(Sequences.simple(ImmutableList.of(s1, s3)), Sequences.simple(ImmutableList.of(s2)))).flatMerge(seq -> seq, noOrderScan.getResultOrdering());
    List<ScanResultValue> noOrderList = noOrderSeq.toList();
    Assert.assertEquals(3, noOrderList.size());
    // Ascending
    Sequence<ScanResultValue> ascendingOrderSeq = Sequences.simple(ImmutableList.of(Sequences.simple(ImmutableList.of(s1)), Sequences.simple(ImmutableList.of(s2)))).flatMerge(seq -> seq, ascendingOrderScan.getResultOrdering());
    List<ScanResultValue> ascendingList = ascendingOrderSeq.toList();
    Assert.assertEquals(2, ascendingList.size());
    Assert.assertEquals(s1, ascendingList.get(0));
    Assert.assertEquals(s2, ascendingList.get(1));
    // Descending
    Sequence<ScanResultValue> descendingOrderSeq = Sequences.simple(ImmutableList.of(Sequences.simple(ImmutableList.of(s1)), Sequences.simple(ImmutableList.of(s2)))).flatMerge(seq -> seq, descendingOrderScan.getResultOrdering());
    List<ScanResultValue> descendingList = descendingOrderSeq.toList();
    Assert.assertEquals(2, descendingList.size());
    Assert.assertEquals(s2, descendingList.get(0));
    Assert.assertEquals(s1, descendingList.get(1));
}

