public void testTimeseriesGrandTotal() {
    TimeseriesQuery query = Druids.newTimeseriesQueryBuilder().dataSource(QueryRunnerTestHelper.dataSource).granularity(QueryRunnerTestHelper.dayGran).intervals(QueryRunnerTestHelper.firstToThird).aggregators(Arrays.asList(QueryRunnerTestHelper.rowsCount, QueryRunnerTestHelper.indexLongSum, QueryRunnerTestHelper.qualityUniques)).postAggregators(QueryRunnerTestHelper.addRowsIndexConstant).descending(descending).context(ImmutableMap.of(TimeseriesQuery.CTX_GRAND_TOTAL, true)).build();
    List<Result<TimeseriesResultValue>> expectedResults = new ArrayList<>();
    expectedResults.add(new Result<>(DateTimes.of("2011-04-01"), new TimeseriesResultValue(ImmutableMap.of("rows", 13L, "index", 6619L, "uniques", QueryRunnerTestHelper.UNIQUES_9, QueryRunnerTestHelper.addRowsIndexConstantMetric, 6633.0))));
    expectedResults.add(new Result<>(DateTimes.of("2011-04-02"), new TimeseriesResultValue(ImmutableMap.of("rows", 13L, "index", 5827L, "uniques", QueryRunnerTestHelper.UNIQUES_9, QueryRunnerTestHelper.addRowsIndexConstantMetric, 5841.0))));
    if (descending) {
        Collections.reverse(expectedResults);
    }
    expectedResults.add(new Result<>(null, new TimeseriesResultValue(ImmutableMap.of("rows", 26L, "index", 12446L, "uniques", QueryRunnerTestHelper.UNIQUES_9, QueryRunnerTestHelper.addRowsIndexConstantMetric, 12473.0))));
    // Must create a toolChest so we can run mergeResults (which applies grand totals).
    QueryToolChest<Result<TimeseriesResultValue>, TimeseriesQuery> toolChest = new TimeseriesQueryQueryToolChest(QueryRunnerTestHelper.noopIntervalChunkingQueryRunnerDecorator());
    // Must wrapped in a results finalizer to stop the runner's builtin finalizer from being called.
    final FinalizeResultsQueryRunner finalRunner = new FinalizeResultsQueryRunner(toolChest.mergeResults(runner), toolChest);
    final List results = finalRunner.run(QueryPlus.wrap(query), CONTEXT).toList();
    TestHelper.assertExpectedResults(expectedResults, results);
}

