    String json = mapper.writeValueAsString(new ColumnCapabilitiesImpl().setDictionaryEncoded(true).setHasBitmapIndexes(true).setHasMultipleValues(true).setHasSpatialIndexes(true).setType(ValueType.COMPLEX).setFilterable(true));
