@Test
public void testUnparseableNumerics() throws IndexSizeExceededException {
    IncrementalIndex<?> index = closerRule.closeLater(indexCreator.createIndex());
    IncrementalIndexAddResult result;
    result = index.add(new MapBasedInputRow(0, Lists.newArrayList("string", "float", "long", "double"), ImmutableMap.of("string", "A", "float", "19.0", "long", "asdj", "double", 21.0d)));
    Assert.assertEquals(ParseException.class, result.getParseException().getClass());
    Assert.assertEquals("Found unparseable columns in row: [MapBasedInputRow{timestamp=1970-01-01T00:00:00.000Z, event={string=A, float=19.0, long=asdj, double=21.0}, dimensions=[string, float, long, double]}], exceptions: [could not convert value [asdj] to long,]", result.getParseException().getMessage());
    result = index.add(new MapBasedInputRow(0, Lists.newArrayList("string", "float", "long", "double"), ImmutableMap.of("string", "A", "float", "aaa", "long", 20, "double", 21.0d)));
    Assert.assertEquals(ParseException.class, result.getParseException().getClass());
    Assert.assertEquals("Found unparseable columns in row: [MapBasedInputRow{timestamp=1970-01-01T00:00:00.000Z, event={string=A, float=aaa, long=20, double=21.0}, dimensions=[string, float, long, double]}], exceptions: [could not convert value [aaa] to float,]", result.getParseException().getMessage());
    result = index.add(new MapBasedInputRow(0, Lists.newArrayList("string", "float", "long", "double"), ImmutableMap.of("string", "A", "float", 19.0, "long", 20, "double", "")));
    Assert.assertEquals(ParseException.class, result.getParseException().getClass());
    Assert.assertEquals("Found unparseable columns in row: [MapBasedInputRow{timestamp=1970-01-01T00:00:00.000Z, event={string=A, float=19.0, long=20, double=}, dimensions=[string, float, long, double]}], exceptions: [could not convert value [] to double,]", result.getParseException().getMessage());
}

