@Test(timeout = 60_000L)
public void testSimple() throws Exception {
    curator.start();
    curator.blockUntilConnected();
    AtomicReference<String> currLeader = new AtomicReference<>();
    String latchPath = "/testlatchPath";
    CuratorDruidLeaderSelector leaderSelector1 = new CuratorDruidLeaderSelector(curator, new DruidNode("s1", "h1", false, 8080, null, true, false), latchPath);
    leaderSelector1.registerListener(new DruidLeaderSelector.Listener() {

        @Override
        public void becomeLeader() {
            logger.info("listener1.becomeLeader().");
            currLeader.set("h1:8080");
            throw new RuntimeException("I am Rogue.");
        }

        @Override
        public void stopBeingLeader() {
            logger.info("listener1.stopBeingLeader().");
            throw new RuntimeException("I said I am Rogue.");
        }
    });
    while (!"h1:8080".equals(currLeader.get())) {
        logger.info("current leader = [%s]", currLeader.get());
        Thread.sleep(100);
    }
    Assert.assertTrue(leaderSelector1.localTerm() >= 1);
    CuratorDruidLeaderSelector leaderSelector2 = new CuratorDruidLeaderSelector(curator, new DruidNode("s2", "h2", false, 8080, null, true, false), latchPath);
    leaderSelector2.registerListener(new DruidLeaderSelector.Listener() {

        private AtomicInteger attemptCount = new AtomicInteger(0);

        @Override
        public void becomeLeader() {
            logger.info("listener2.becomeLeader().");
            if (attemptCount.getAndIncrement() < 1) {
                throw new RuntimeException("will become leader on next attempt.");
            }
            currLeader.set("h2:8080");
        }

        @Override
        public void stopBeingLeader() {
            logger.info("listener2.stopBeingLeader().");
            throw new RuntimeException("I am broken.");
        }
    });
    while (!"h2:8080".equals(currLeader.get())) {
        logger.info("current leader = [%s]", currLeader.get());
        Thread.sleep(100);
    }
    Assert.assertTrue(leaderSelector2.isLeader());
    Assert.assertEquals("http://h2:8080", leaderSelector1.getCurrentLeader());
    Assert.assertEquals(2, leaderSelector2.localTerm());
    CuratorDruidLeaderSelector leaderSelector3 = new CuratorDruidLeaderSelector(curator, new DruidNode("s3", "h3", false, 8080, null, true, false), latchPath);
    leaderSelector3.registerListener(new DruidLeaderSelector.Listener() {

        @Override
        public void becomeLeader() {
            logger.info("listener3.becomeLeader().");
            currLeader.set("h3:8080");
        }

        @Override
        public void stopBeingLeader() {
            logger.info("listener3.stopBeingLeader().");
        }
    });
    leaderSelector2.unregisterListener();
    while (!"h3:8080".equals(currLeader.get())) {
        logger.info("current leader = [%s]", currLeader.get());
        Thread.sleep(100);
    }
    Assert.assertTrue(leaderSelector3.isLeader());
    Assert.assertEquals("http://h3:8080", leaderSelector1.getCurrentLeader());
    Assert.assertEquals(1, leaderSelector3.localTerm());
}

@Test(timeout = 60_000L)
public void testAnnouncementAndDiscovery() throws Exception {
    ObjectMapper objectMapper = new DefaultObjectMapper();
    //additional setup to serde DruidNode
    objectMapper.setInjectableValues(new InjectableValues.Std().addValue(ServerConfig.class, new ServerConfig()).addValue("java.lang.String", "dummy").addValue("java.lang.Integer", 1234));
    curator.start();
    curator.blockUntilConnected();
    Announcer announcer = new Announcer(curator, Execs.directExecutor());
    announcer.start();
    CuratorDruidNodeAnnouncer druidNodeAnnouncer = new CuratorDruidNodeAnnouncer(announcer, new ZkPathsConfig(), objectMapper);
    DiscoveryDruidNode node1 = new DiscoveryDruidNode(new DruidNode("s1", "h1", false, 8080, null, true, false), NodeType.COORDINATOR, ImmutableMap.of());
    DiscoveryDruidNode node2 = new DiscoveryDruidNode(new DruidNode("s2", "h2", false, 8080, null, true, false), NodeType.COORDINATOR, ImmutableMap.of());
    DiscoveryDruidNode node3 = new DiscoveryDruidNode(new DruidNode("s3", "h3", false, 8080, null, true, false), NodeType.OVERLORD, ImmutableMap.of());
    DiscoveryDruidNode node4 = new DiscoveryDruidNode(new DruidNode("s4", "h4", false, 8080, null, true, false), NodeType.OVERLORD, ImmutableMap.of());
    druidNodeAnnouncer.announce(node1);
    druidNodeAnnouncer.announce(node3);
    CuratorDruidNodeDiscoveryProvider druidNodeDiscoveryProvider = new CuratorDruidNodeDiscoveryProvider(curator, new ZkPathsConfig(), objectMapper);
    druidNodeDiscoveryProvider.start();
    DruidNodeDiscovery coordDiscovery = druidNodeDiscoveryProvider.getForNodeType(NodeType.COORDINATOR);
    DruidNodeDiscovery overlordDiscovery = druidNodeDiscoveryProvider.getForNodeType(NodeType.OVERLORD);
    while (!checkNodes(ImmutableSet.of(node1), coordDiscovery.getAllNodes())) {
        Thread.sleep(100);
    }
    while (!checkNodes(ImmutableSet.of(node3), overlordDiscovery.getAllNodes())) {
        Thread.sleep(100);
    }
    HashSet<DiscoveryDruidNode> coordNodes = new HashSet<>();
    coordDiscovery.registerListener(new DruidNodeDiscovery.Listener() {

        @Override
        public void nodesAdded(Collection<DiscoveryDruidNode> nodes) {
            coordNodes.addAll(nodes);
        }

        @Override
        public void nodesRemoved(Collection<DiscoveryDruidNode> nodes) {
            coordNodes.removeAll(nodes);
        }
    });
    HashSet<DiscoveryDruidNode> overlordNodes = new HashSet<>();
    overlordDiscovery.registerListener(new DruidNodeDiscovery.Listener() {

        @Override
        public void nodesAdded(Collection<DiscoveryDruidNode> nodes) {
            overlordNodes.addAll(nodes);
        }

        @Override
        public void nodesRemoved(Collection<DiscoveryDruidNode> nodes) {
            overlordNodes.removeAll(nodes);
        }
    });
    while (!checkNodes(ImmutableSet.of(node1), coordNodes)) {
        Thread.sleep(100);
    }
    while (!checkNodes(ImmutableSet.of(node3), overlordNodes)) {
        Thread.sleep(100);
    }
    druidNodeAnnouncer.announce(node2);
    druidNodeAnnouncer.announce(node4);
    while (!checkNodes(ImmutableSet.of(node1, node2), coordDiscovery.getAllNodes())) {
        Thread.sleep(100);
    }
    while (!checkNodes(ImmutableSet.of(node3, node4), overlordDiscovery.getAllNodes())) {
        Thread.sleep(100);
    }
    while (!checkNodes(ImmutableSet.of(node1, node2), coordNodes)) {
        Thread.sleep(100);
    }
    while (!checkNodes(ImmutableSet.of(node3, node4), overlordNodes)) {
        Thread.sleep(100);
    }
    druidNodeAnnouncer.unannounce(node1);
    druidNodeAnnouncer.unannounce(node2);
    druidNodeAnnouncer.unannounce(node3);
    druidNodeAnnouncer.unannounce(node4);
    while (!checkNodes(ImmutableSet.of(), coordDiscovery.getAllNodes())) {
        Thread.sleep(100);
    }
    while (!checkNodes(ImmutableSet.of(), overlordDiscovery.getAllNodes())) {
        Thread.sleep(100);
    }
    while (!coordNodes.isEmpty()) {
        Thread.sleep(100);
    }
    while (!overlordNodes.isEmpty()) {
        Thread.sleep(100);
    }
    druidNodeDiscoveryProvider.stop();
    announcer.stop();
}

