@Test
public void testEntryAndStatus() throws Exception {
    Map<String, Integer> entry = ImmutableMap.of("numericId", 1234);
    Map<String, Integer> status1 = ImmutableMap.of("count", 42);
    Map<String, Integer> status2 = ImmutableMap.of("count", 42, "temp", 1);
    final String entryId = "1234";
    handler.insert(entryId, DateTimes.of("2014-01-02T00:00:00.123"), "testDataSource", entry, true, null);
    Assert.assertEquals(Optional.of(entry), handler.getEntry(entryId));
    Assert.assertEquals(Optional.absent(), handler.getEntry("non_exist_entry"));
    Assert.assertEquals(Optional.absent(), handler.getStatus(entryId));
    Assert.assertEquals(Optional.absent(), handler.getStatus("non_exist_entry"));
    Assert.assertTrue(handler.setStatus(entryId, true, status1));
    Assert.assertEquals(ImmutableList.of(Pair.of(entry, status1)), handler.getActiveTaskInfo(null).stream().map(taskInfo -> Pair.of(taskInfo.getTask(), taskInfo.getStatus())).collect(Collectors.toList()));
    Assert.assertTrue(handler.setStatus(entryId, true, status2));
    Assert.assertEquals(ImmutableList.of(Pair.of(entry, status2)), handler.getActiveTaskInfo(null).stream().map(taskInfo -> Pair.of(taskInfo.getTask(), taskInfo.getStatus())).collect(Collectors.toList()));
    Assert.assertEquals(ImmutableList.of(), handler.getCompletedTaskInfo(DateTimes.of("2014-01-01"), null, null));
    Assert.assertTrue(handler.setStatus(entryId, false, status1));
    Assert.assertEquals(Optional.of(status1), handler.getStatus(entryId));
    // inactive statuses cannot be updated, this should fail
    Assert.assertFalse(handler.setStatus(entryId, false, status2));
    Assert.assertEquals(Optional.of(status1), handler.getStatus(entryId));
    Assert.assertEquals(Optional.of(entry), handler.getEntry(entryId));
    Assert.assertEquals(ImmutableList.of(), handler.getCompletedTaskInfo(DateTimes.of("2014-01-03"), null, null));
    Assert.assertEquals(ImmutableList.of(status1), handler.getCompletedTaskInfo(DateTimes.of("2014-01-01"), null, null).stream().map(TaskInfo::getStatus).collect(Collectors.toList()));
}

