@Test
public void testPublishPerRow() throws IOException, InterruptedException, TimeoutException, ExecutionException {
    final TestCommitterSupplier<Integer> committerSupplier = new TestCommitterSupplier<>();
    Assert.assertNull(driver.startJob());
    // Add the first row and publish immediately
    {
        committerSupplier.setMetadata(1);
        Assert.assertTrue(driver.add(ROWS.get(0), "dummy", committerSupplier, false, true).isOk());
        final SegmentsAndMetadata segmentsAndMetadata = driver.publishAndRegisterHandoff(makeOkPublisher(), committerSupplier.get(), ImmutableList.of("dummy")).get(PUBLISH_TIMEOUT_MILLIS, TimeUnit.MILLISECONDS);
        Assert.assertEquals(ImmutableSet.of(new SegmentIdWithShardSpec(DATA_SOURCE, Intervals.of("2000/PT1H"), VERSION, new NumberedShardSpec(0, 0))), asIdentifiers(segmentsAndMetadata.getSegments()));
        Assert.assertEquals(1, segmentsAndMetadata.getCommitMetadata());
    }
    // Add the second and third rows and publish immediately
    for (int i = 1; i < ROWS.size(); i++) {
        committerSupplier.setMetadata(i + 1);
        Assert.assertTrue(driver.add(ROWS.get(i), "dummy", committerSupplier, false, true).isOk());
        final SegmentsAndMetadata segmentsAndMetadata = driver.publishAndRegisterHandoff(makeOkPublisher(), committerSupplier.get(), ImmutableList.of("dummy")).get(PUBLISH_TIMEOUT_MILLIS, TimeUnit.MILLISECONDS);
        Assert.assertEquals(ImmutableSet.of(// The second and third rows have the same dataSource, interval, and version, but different shardSpec of
        // different partitionNum
        new SegmentIdWithShardSpec(DATA_SOURCE, Intervals.of("2000T01/PT1H"), VERSION, new NumberedShardSpec(i - 1, 0))), asIdentifiers(segmentsAndMetadata.getSegments()));
        Assert.assertEquals(i + 1, segmentsAndMetadata.getCommitMetadata());
    }
    driver.persist(committerSupplier.get());
    // There is no remaining rows in the driver, and thus the result must be empty
    final SegmentsAndMetadata segmentsAndMetadata = driver.publishAndRegisterHandoff(makeOkPublisher(), committerSupplier.get(), ImmutableList.of("dummy")).get(PUBLISH_TIMEOUT_MILLIS, TimeUnit.MILLISECONDS);
    Assert.assertEquals(ImmutableSet.of(), asIdentifiers(segmentsAndMetadata.getSegments()));
    Assert.assertEquals(3, segmentsAndMetadata.getCommitMetadata());
}

