    final List<Future> futures = new ArrayList<>(NUM_THREADS);
    for (int i = 0; i < NUM_THREADS; i++) {
        futures.add(exec.submit(() -> {
            try {
                segmentAnnouncer.announceSegments(testSegments);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }));
    }
