public void testStartStop() throws Exception {
    EasyMock.reset(configManager);
    EasyMock.expect(configManager.watch(EasyMock.eq(LookupCoordinatorManager.LOOKUP_CONFIG_KEY), EasyMock.<TypeReference>anyObject(), EasyMock.<AtomicReference>isNull())).andReturn(new AtomicReference<List<LookupExtractorFactoryMapContainer>>(null)).once();
