    // All of these queries are unplannable because they rely on features Druid doesn't support.
    // This test is here to confirm that we don't fall back to Calcite's interpreter or enumerable implementation.
    // It's also here so when we do support these features, we can have "real" tests for these queries.
    final List<String> queries = ImmutableList.of(// SELECT query with order by
    "SELECT dim1 FROM druid.foo ORDER BY dim1", // Self-join
    "SELECT COUNT(*) FROM druid.foo x, druid.foo y", // DISTINCT with OFFSET
    "SELECT DISTINCT dim2 FROM druid.foo ORDER BY dim2 LIMIT 2 OFFSET 5", // NOT IN subquery
    "SELECT COUNT(*) FROM foo WHERE dim1 NOT IN (SELECT dim1 FROM foo WHERE dim2 = 'a')", "EXPLAIN PLAN FOR SELECT COUNT(*) FROM foo WHERE dim1 IN (SELECT dim1 FROM foo WHERE dim2 = 'a')\n" + // AND of two IN subqueries
    "AND dim1 IN (SELECT dim1 FROM foo WHERE m2 > 2)");
    for (final String query : queries) {
        assertQueryIsUnplannable(query);
    }
}

@Test
public void testUnplannableExactCountDistinctQueries() {
    // All of these queries are unplannable in exact COUNT DISTINCT mode.
    final List<String> queries = ImmutableList.of(// two COUNT DISTINCTs, same query
    "SELECT COUNT(distinct dim1), COUNT(distinct dim2) FROM druid.foo", // two COUNT DISTINCTs
    "SELECT dim1, COUNT(distinct dim1), COUNT(distinct dim2) FROM druid.foo GROUP BY dim1", // COUNT DISTINCT on sketch cannot be exact
    "SELECT COUNT(distinct unique_dim1) FROM druid.foo");
    for (final String query : queries) {
        assertQueryIsUnplannable(PLANNER_CONFIG_NO_HLL, query);
    }
}

